sections.usage:
# Render with the kit: irender render page.yaml --ui-kit
version: 1
state: { name: "" }
root:
  type: ui-card
  props: { title: Welcome, description: Every component is plain config. }
  children:
    - { type: ui-input, props: { bind: name, placeholder: Your name } }
    - type: ui-button
      props: { label: "Say hi to {{ name || 'you' }}" }
      on: { click: { action: set_state, key: toast, value: { title: Hi! } } }

- { type: ui-theme-toggle }                                   # System, Light, Dark
- { type: ui-theme-option, props: { option: palette, swatch: color.primary } }
- { type: ui-popover, props: { trigger: Theme }, children: [ { type: ui-theme-panel } ] }

- type: ui-button
  props: { label: Save, variant: default, size: sm, icon: check }
  on: { click: { action: submit, endpoint: /api/save, method: POST } }
- { type: ui-button, props: { label: Docs, variant: link, href: /docs } }

- type: ui-split-button
  props: { label: Download PDF }
  on: { click: { action: call, name: download, args: { format: pdf } } }
  children:
    - { type: ui-menu-item, props: { label: Excel }, on: { click: { action: call, name: download, args: { format: xlsx } } } }

- { type: ui-toggle, props: { bind: bold, label: Bold } }
- { type: ui-toggle-group, props: { bind: align, options: [left, center, right] } }
- { type: ui-slider, props: { bind: volume, min: 0, max: 100, step: 5 } }

- { type: ui-label, props: { text: Email, for: email } }
- { type: ui-input, props: { bind: email, type: email, placeholder: you@example.com }, attrs: { id: email } }
- { type: ui-select, props: { bind: plan, options: [Free, Pro, Team] } }
- { type: ui-checkbox, props: { bind: terms, label: I accept the terms } }
- { type: ui-radio-group, props: { bind: size, options: [S, M, L] } }

- type: ui-field
  props: { label: Username, description: 3 to 20 letters, error: "{{ username.length < 3 ? 'Too short' : '' }}" }
  children: [ { type: ui-input, props: { bind: username } } ]
- type: ui-input-group
  props: { prefix: "https://", suffix: .com }
  children: [ { type: ui-input, props: { bind: site } } ]

- type: ui-field
  props: { label: Verification code, error: "{{ codeError }}" }
  children:
    - type: ui-input-otp
      props: { bind: code, length: 6, groups: [3, 3] }
      on: { complete: { action: submit, endpoint: /api/verify, method: POST, body: { code: "{{ code }}" }, into: result } }

- type: ui-field
  props: { label: Budget }
  children:
    - { type: ui-number-input, props: { bind: budget, currency: INR, locale: en-IN, min: 0 } }
- { type: ui-number-input, props: { bind: qty, min: 1, max: 99, stepper: true, suffix: pcs, label: Quantity } }

- type: ui-field
  props: { label: Payload }
  children:
    - { type: ui-json-editor, props: { bind: payload, bindValid: payloadOk, type: object } }

- type: ui-date-picker
  props: { bind: period, bindRange: periodDates, mode: range, months: 2, presets: [last7, thisMonth, yearToDate], compare: true, bindCompare: periodVs }
- { type: ui-date-picker, props: { bind: due, input: true, min: today, bindError: dueError } }
- { type: ui-calendar, props: { bind: days, mode: multiple, disabledDays: [0, 6] } }

- type: ui-color-picker
  props: { bind: brand, alpha: true, clearable: true, swatches: ["#0f172a", "#2563eb", { value: "#ffffff", label: White }] }
- { type: ui-color-picker, props: { bind: tint, inline: true, format: rgb } }
- { type: ui-color-picker, props: { bind: tag, custom: false, swatches: ["#ef4444", "#22c55e"] } }

- { type: ui-rating, props: { bind: stars, label: Rate your stay } }
- { type: ui-rating, props: { value: "{{ hotel.average }}" } }   # read-only
- { type: ui-input, props: { bind: password, type: password } }
- { type: ui-password-checklist, props: { value: "{{ password }}", bindValid: strong } }

- type: ui-form
  props:
    columns: 2
    bindErrors: errors
    bindDirty: dirty
    guard: true
    rules: { email: { label: Email, required: true, type: email } }
  on: { submit: { action: submit, endpoint: /api/save, method: POST, body: { email: "{{ email }}" } } }
  children:
    - { type: ui-error-summary }
    - type: ui-form-section
      props: { title: Contact, columns: 2, span: full }
      children:
        - { type: ui-field, props: { label: Email, error: "{{ errors.email }}" }, children: [ { type: ui-input, props: { bind: email } } ] }
        - { type: ui-field, props: { label: Phone }, children: [ { type: ui-input, props: { bind: phone } } ] }
    - { type: ui-save-bar }

- type: ui-stepper
  props: { bind: step, finishLabel: Send }
  on: { finish: { action: call, name: send } }
  children:
    - { type: ui-step, props: { value: who, label: About you, valid: "{{ name != '' }}" }, children: [ … ] }
    - { type: ui-step, props: { value: check, label: Check }, children: [ … ] }

- type: ui-repeater
  props:
    bind: lines
    reorderable: true
    bindTotals: totals
    fields:
      - { field: item, label: Item, required: true }
      - { field: qty, label: Qty, type: number, default: 1 }
      - { field: price, label: Price, type: currency }
      - { field: total, label: Total, compute: qty * price, summary: sum }

- type: ui-sortable-list
  props: { bind: priorities, numbered: true, removable: true }
  children:
    - { type: text, props: { value: "{{ item.label }}" } }
- { type: ui-sortable-list, props: { bind: menuOrder } }   # plain values

- type: ui-form-builder
  props: { bind: fields, bindDocument: formDoc, submitLabel: Sign in }
# fields: [{ id: name, type: text, label: Your name, required: true }, { id: team, type: select, label: Team, options: [A, B] }]

- { type: ui-tags-input, props: { bind: topics, suggestions: [Design, Legal], max: 5 } }
- { type: ui-masked-input, props: { bind: card, mask: card } }
- { type: ui-phone-input, props: { bind: phone, country: IN, bindValid: ok } }
- { type: ui-time-picker, props: { bind: start, min: "09:00", max: "18:00", step: 15 } }
- { type: ui-mention-input, props: { bind: note, people: "{{ people }}", bindMentions: named } }

- { type: ui-qr-code, props: { value: "https://example.com/t/{{ ticket }}", download: ticket.png, logo: /logo.svg } }
- { type: ui-barcode, props: { value: "{{ sku }}", type: code128 } }
- { type: ui-code-scanner, props: { bind: code, bindList: scanned, continuous: true } }

- { type: ui-badge, props: { text: New, variant: secondary } }
- { type: ui-badge, props: { text: Paid, variant: success, dot: true } }
- { type: ui-kbd, props: { text: ⌘K } }

- type: ui-card
  props: { title: Create project, description: Deploy in one click. }
  children:
    - { type: ui-input, props: { bind: project, placeholder: Name } }
    - type: ui-card-footer
      children: [ { type: ui-button, props: { label: Deploy } } ]

- { type: ui-avatar, props: { src: /me.jpg, alt: Kaushik, fallback: KS } }
- type: ui-aspect-ratio
  props: { ratio: "16 / 9" }
  children: [ { type: element, props: { tag: img }, attrs: { src: /cover.jpg, alt: "" } } ]

- type: ui-table
  props: { caption: Recent invoices }
  children:
    - type: list
      props: { tag: tbody, items: "{{ invoices }}", as: inv }
      children:
        - { type: element, props: { tag: tr }, children: [ { type: text, props: { tag: td, value: "{{ inv.id }}" } } ] }

- type: ui-data-table
  props: { rows: "{{ orders }}", search: true, selectable: true, bindSelection: picked, pageSize: 10 }
  children:
    - { type: ui-data-table-column, props: { field: date, format: date, filter: date } }
    - { type: ui-data-table-column, props: { field: amount, format: currency, filter: range, summary: sum } }
    - { type: ui-data-table-column, props: { field: status, filter: select, cell: badge } }

- type: ui-filters
  props: { bind: filters, rows: "{{ orders }}", currency: INR }
  children:
    - { type: ui-filter, props: { field: status, label: Status } }      # values from rows, with counts
    - { type: ui-filter, props: { field: amount, label: Amount, type: currency } }
    - { type: ui-filter, props: { field: date, label: Date, type: date } }
- type: ui-data-table
  props: { rows: "{{ orders }}", filter: "{{ filters }}" }

- { type: ui-heading, props: { level: 2, text: Settings } }
- { type: ui-text, props: { variant: muted, text: Manage your account. } }
- { type: ui-separator, props: { label: Or continue with } }

- type: ui-data-table
  props: { rows: "{{ products }}", addRow: true, deletable: true, bindChanges: changes, bindErrors: wrong, export: products.xlsx }
  children:
    - { type: ui-data-table-column, props: { field: sku, edit: text, required: true, unique: true } }
    - { type: ui-data-table-column, props: { field: price, edit: number, min: 1, format: currency } }
    - { type: ui-data-table-column, props: { field: status, edit: select, options: [Live, Paused] } }

- type: ui-gauge
  props: { value: "{{ oee }}", unit: "%", target: 85, bands: [{ to: 60, tone: danger }, { to: 85, tone: warning }, { tone: success }] }
- { type: ui-gauge, props: { value: "{{ oil }}", min: 20, max: 120, unit: °C, shape: half, needle: true } }

- type: ui-description-list
  props: { columns: 3 }
  children:
    - { type: ui-description-item, props: { label: Account, value: DE89 3704, copy: true } }
    - { type: ui-description-item, props: { label: Owner, bind: owner } }
- type: ui-item-group
  children:
    - { type: ui-item, props: { title: Backup codes, description: 8 left, icon: lock }, children: [ { type: ui-button, props: { label: View, size: sm } } ] }

- type: ui-plan
  props: { items: "{{ seats }}", bindItems: seats, bind: seat, image: floor.svg, width: 1000, height: 600, tones: { Free: success, Taken: danger }, legend: true, search: true }
- type: ui-plan
  props: { layout: { kind: aircraft, rows: 30, seats: "ABC DEF", exits: [12], status: Free }, data: "{{ taken }}", bind: seats, multiple: true, max: 2, available: [Free], bindTotal: total }
- type: ui-plan
  props: { bindFloor: floor, floors: [ { id: f1, label: "1", layout: { kind: office, pods: 6 } }, { id: g, label: G, items: "{{ rooms }}" } ] }

- { type: ui-toaster, props: { bind: toast } }
- type: ui-button
  props: { label: Save }
  on: { click: { action: set_state, key: toast, value: { title: Saved, description: Your changes are live., variant: success } } }

- { type: ui-illustration, props: { name: not-found, size: 320 } }
- { type: ui-illustration, props: { name: out-of-stock, primary: "#0ea5e9", secondary: "#f43f5e" } }
- type: ui-empty
  props: { illustration: no-data, title: No data yet, description: Orders show up here. }
  children: [ { type: ui-button, props: { label: Import orders } } ]

- { type: ui-spinner, props: { label: Loading orders } }
- { type: ui-empty, props: { title: No projects yet, description: Create your first one. } }
- { type: ui-scroll-area, props: { height: 200 }, children: [ … ] }

- type: ui-dialog
  props: { trigger: Edit profile, title: Edit profile, description: Make changes here. }
  children:
    - { type: ui-input, props: { bind: name } }
    - type: ui-dialog-footer
      children: [ { type: ui-dialog-close, props: { label: Save } } ]

- type: ui-dropdown-menu
  props: { trigger: My account }
  children:
    - { type: ui-menu-label, props: { text: Signed in as Ada } }
    - { type: ui-menu-item, props: { label: Profile, shortcut: ⇧⌘P } }
    - { type: ui-menu-separator }
    - { type: ui-menu-item, props: { label: Log out, variant: destructive } }
- { type: ui-tooltip, props: { text: Add to library }, children: [ { type: ui-button, props: { label: + } } ] }

- type: ui-context-menu
  props: { bind: file }
  children:
    - { type: element, attrs: { data-context: Report.pdf }, children: [ { type: text, props: { value: Report.pdf } } ] }
    - { type: ui-menu-item, props: { label: "Open {{ file }}" } }
    - { type: ui-menu-item, props: { label: Delete, variant: destructive } }

- type: ui-command-dialog
  props: { trigger: Search, shortcut: mod+k }
  children:
    - type: ui-command-group
      props: { heading: Pages }
      children:
        - { type: ui-command-item, props: { label: Dashboard, href: /dashboard } }
        - { type: ui-command-item, props: { label: Settings, keywords: [preferences], href: /settings } }

- type: ui-tabs
  props: { bind: tab }
  children:
    - { type: ui-tab-panel, props: { value: account, label: Account }, children: [ … ] }
    - { type: ui-tab-panel, props: { value: password, label: Password }, children: [ … ] }

- type: ui-menubar
  children:
    - type: ui-menubar-menu
      props: { label: File }
      children:
        - { type: ui-menu-item, props: { label: New tab, shortcut: ⌘T } }
        - type: ui-menu-sub
          props: { label: Share }
          children: [ { type: ui-menu-item, props: { label: Email link } } ]
    - type: ui-menubar-menu
      props: { label: View }
      children:
        - { type: ui-menu-checkbox, props: { label: Show status bar, bind: statusBar } }
        - { type: ui-menu-radio-group, props: { bind: zoom, options: [100%, 125%, 150%] } }

- type: ui-navigation-menu
  children:
    - type: ui-navigation-item
      props: { label: Products, width: 420 }
      children:
        - { type: ui-navigation-link, props: { label: Analytics, href: /analytics, description: See what's happening } }
        - { type: ui-navigation-link, props: { label: Automation, href: /automation, description: Let it run itself } }
    - { type: ui-navigation-link, props: { label: Docs, href: /docs, active: true } }

- type: ui-resizable
  props: { bind: panes, handle: true }
  children:
    - { type: ui-resizable-panel, props: { size: 25, min: 15, collapsible: true }, children: [ ... ] }
    - { type: ui-resizable-panel, children: [ ... ] }

- type: ui-dashboard-grid
  props: { bind: layout, rowHeight: 80 }
  children:
    - { type: ui-tile, props: { id: sales, title: Sales, x: 0, y: 0, w: 8, h: 4 }, children: [ ... ] }
    - { type: ui-tile, props: { id: goals, title: Goals, x: 8, y: 0, w: 4, h: 4, minW: 3 }, children: [ ... ] }

- type: ui-scroll-spy
  props: { label: On this page, offset: 64 }   # 64px covered by a sticky header
  children:
    - { type: element, props: { tag: a }, attrs: { href: "#install" }, children: [ { type: text, props: { value: Install } } ] }
    - { type: element, props: { tag: a }, attrs: { href: "#usage" }, children: [ { type: text, props: { value: Usage } } ] }

- { type: ui-attachment, props: { files: "{{ files }}", bindFiles: files } }
- { type: ui-sources, props: { text: "Highs reach 18°C [1].", items: [ { title: City guide, url: "https://example.com" } ] } }
- { type: ui-tool-call, props: { title: Cancel the booking, status: approval, input: { id: 42 }, bindApproval: allowed } }

- type: ui-carousel
  props: { label: Featured, size: 280 }
  children: [ { type: ui-card, props: { title: One } }, { type: ui-card, props: { title: Two } } ]

app: { name: Field notes, themeColor: "#2563eb", icon: { text: FN, background: "#2563eb" }, offline: { skip: [/api/] } }
root:
  type: stack
  children:
    - { type: ui-install-prompt, props: { variant: card, remember: install } }
    - { type: ui-update-prompt, props: { text: "Faster search, and a new report." } }

- { type: ui-offline-indicator, props: { bind: net, variant: banner, detail: "What you do is kept and sent later." } }
- { type: ui-local-store, props: { keys: [draft], name: notes } }
- { type: ui-offline-queue, props: { paths: [/api/], labels: { /api/records: Report }, labelField: title, bindCount: waiting } }

- type: ui-app-shell
  props: { bind: screen, pullToRefresh: true, history: true }
  children:
    - { type: ui-app-actions, children: [ { type: ui-offline-indicator } ] }
    - { type: ui-app-screen, props: { value: jobs, label: Jobs, icon: list, badge: "{{ waiting }}" } }
    - { type: ui-app-screen, props: { value: job, label: Job, parent: jobs } }
    - { type: ui-app-screen, props: { value: more, label: More, icon: menu } }

app: { name: Keep, share: { url: "./new.html", accept: ["image/*"] } }
# on new.html:
- { type: ui-share-target, props: { bind: shared }, on: { accept: { action: submit, endpoint: /api/items, body: { item: "{{ shared }}" } } } }
- { type: ui-share, props: { title: Trip, url: "/trips/42", files: "{{ photos }}" } }
- { type: ui-contact-picker, props: { bind: people, multiple: true } }

- { type: ui-location, props: { bind: here, watch: true, enough: 25 } }
- type: ui-geo-checkin
  props: { bind: visit, bindLog: visits, places: [ { id: a, name: Depot, lat: 38.708, lng: -9.137, radius: 120 } ], outside: reason, photo: "{{ photo }}" }
  children: [ { type: ui-camera, props: { bind: photo } } ]

- { type: ui-audio-recorder, props: { bind: notes, multiple: true, max: 120 } }
- { type: ui-video-recorder, props: { bind: clip, max: 30, facing: back } }
- { type: ui-screen-capture, props: { bind: screenshot, modes: [picture] } }

- type: ui-swipe-actions
  props: { label: "{{ m.from }}", start: [ { value: read, label: Read, tone: info } ], end: [ { value: delete, label: Delete, tone: danger } ] }
  on: { delete: { action: submit, endpoint: "/api/mail/{{ m.id }}", method: DELETE } }
  children: [ { type: ui-item, props: { title: "{{ m.from }}" } } ]
- { type: ui-wake-lock, props: { bind: cooking } }
